INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'A fabric''s greige (unprocessed) weight is 100 kg, and after wet processing (scouring, bleaching, dyeing) it weighs 95 kg. What is the approximate processing weight loss percentage?', '["5%","95%","100%","0.95%"]'::jsonb, '5%', 'Weight loss % = ((greige weight − finished weight) / greige weight) × 100 = ((100 − 95) / 100) × 100 = 5%.', 1, '{"processing-weight-loss-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'A fabric''s greige weight is 500 kg, and after wet processing it weighs 465 kg. What is the approximate processing weight loss percentage?', '["7%","93%","35%","0.7%"]'::jsonb, '7%', 'Weight loss % = ((500 − 465) / 500) × 100 = (35/500) × 100 = 7%.', 1, '{"processing-weight-loss-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'A fabric measures 1.60 meters wide before finishing (stentering), and after the stenter sets it to a controlled final width, it measures 1.52 meters. What is the approximate width shrinkage percentage?', '["5%","1.52%","8%","95%"]'::jsonb, '5%', 'Width shrinkage % = ((initial width − final width) / initial width) × 100 = ((1.60 − 1.52) / 1.60) × 100 = 5%.', 2, '{"width-shrinkage-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'A fabric measures 1.70 meters wide before finishing, and after processing measures 1.53 meters. What is the approximate width shrinkage percentage?', '["10%","1.53%","17%","90%"]'::jsonb, '10%', 'Width shrinkage % = ((1.70 − 1.53) / 1.70) × 100 = (0.17/1.70) × 100 = 10%.', 2, '{"width-shrinkage-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'An ETP (effluent treatment plant) processes 2,000 liters of wastewater per hour and operates 20 hours per day. What is the approximate total daily wastewater treatment volume?', '["40,000 liters","2,000 liters","20,000 liters","100 liters"]'::jsonb, '40,000 liters', 'Daily volume = flow rate per hour × operating hours = 2,000 L/hr × 20 hr = 40,000 liters.', 1, '{"etp-volume-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'An ETP processes 3,500 liters of wastewater per hour and operates 16 hours per day. What is the approximate total daily wastewater treatment volume?', '["56,000 liters","3,500 liters","16,000 liters","219 liters"]'::jsonb, '56,000 liters', 'Daily volume = flow rate per hour × operating hours = 3,500 L/hr × 16 hr = 56,000 liters.', 1, '{"etp-volume-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'A dyeing machine''s water consumption is 15 liters per kg of fabric processed. For a 1,200 kg fabric batch, what is the approximate total water consumption?', '["18,000 liters","1,200 liters","15 liters","80 liters"]'::jsonb, '18,000 liters', 'Total water = consumption rate per kg × fabric weight = 15 L/kg × 1,200 kg = 18,000 liters.', 1, '{"water-consumption-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'A dyeing machine''s water consumption is 20 liters per kg of fabric processed. For a 900 kg fabric batch, what is the approximate total water consumption?', '["18,000 liters","900 liters","20 liters","45 liters"]'::jsonb, '18,000 liters', 'Total water = consumption rate per kg × fabric weight = 20 L/kg × 900 kg = 18,000 liters.', 1, '{"water-consumption-calc"}'::text[]);
